import { useState, useEffect } from "react";
import socket from "./socket";
import Login from "./pages/Login";
import Register from "./pages/Register";
import User from "./pages/UserDashboard";
import Provider from "./pages/ProviderDashboard";
import Admin from "./pages/AdminDashboard";
import { CartProvider } from "./context/CartContext";
import { ToastProvider } from "./context/ToastContext";
import ToastContainer from "./components/ToastContainer";

export default function App() {
  const [role, setRole] = useState("");
  const [showRegister, setShowRegister] = useState(false);

  useEffect(() => {
    // Check for existing token
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split(".")[1]));
        setRole(decoded.role);
      } catch (err) {
        localStorage.removeItem("token");
      }
    }

    // global booking updates (log only here; per-page components show toasts)
    socket.on("booking-update", (data) => {
      try {
        if (!data) return;
        const parsed = data;
        console.log("booking-update received:", parsed);
      } catch (err) {
        console.error(err);
      }
    });
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    setRole("");
    setShowRegister(false);
  };

  if (showRegister) {
    return <Register setShowRegister={setShowRegister} />;
  }

  if (!role) {
    return <Login setRole={setRole} setShowRegister={setShowRegister} />;
  }

  return (
    <ToastProvider>
      <CartProvider>
        {role === "user" && <User />}
        {role === "provider" && <Provider />}
        {role === "admin" && <Admin />}
      </CartProvider>
      <ToastContainer />
    </ToastProvider>
  );
}
